"use client";

/**
 * The hero emblem's canvas, loaded only by DotMatrix (next/dynamic, ssr: false).
 *
 * Draws the halftone in content/hero-emblem (generated by scripts/hero-emblem.mjs, the same
 * dots as HeroEmblem's SVG poster): Tokyo Tower on a hexagonal lattice, cropped like
 * object-fit: cover; in each cell either a tower dot (full ink, area by brightness) or a
 * sky dot (ink at 15%, = --line; smaller next to the tower). Poster and canvas line up dot
 * for dot, so the hand-over between them is invisible. The ink is the wrapper's computed
 * color (text-ink, CanvasText under forced colours), read again when the theme or forced
 * colours change.
 *
 * Motion (design 11 HeroEmblem): a slow drift on arrival, and a lens under the pointer
 * (or a finger dragging sideways: touch-action: pan-y keeps vertical swipes for scrolling):
 * the dots within one grid cell, sky included, part around it and spring back, inside an
 * accent ring (the design's "pointer · dots repel", its accent-ring).
 * Accessibility over the design (WCAG 2.2.2): the drift fades out after five seconds, so
 * nothing moves on its own for longer and the emblem needs no pause button; the lens is
 * user-initiated.
 *
 * Runs requestAnimationFrame only while something moves, and only while the browser renders
 * the canvas (MWG "efficient-background-processing": contentvisibilityautostatechange, with
 * IntersectionObserver where content-visibility is unsupported). The wrapper is absolutely
 * positioned with insets, so its size never depends on its content: no contain-intrinsic-size.
 * Each frame is two fills (sky, tower), one path each. DPR capped at 2.
 */
import { useEffect, useRef, useState } from "react";
import { heroEmblemDots as dots } from "@/content/hero-emblem";

const DRIFT_MS = 5000;
const DRIFT_AMPLITUDE = 1.2; // px
const PUSH = 0.4; // furthest push, as a share of the lens radius
const EASE = 0.14; // per frame, towards the target offset
const REST = 0.05; // px: below this a dot counts as settled

const tones = Uint8Array.from(atob(dots.tones), (char) => char.charCodeAt(0));

/** A cell's dot, in cells: [radius, tower?]; radius 0 = none (as the script draws it). */
function dotOf(tone: number): [number, boolean] {
  const tower = dots.towerRadius * Math.sqrt(tone);
  if (tower >= dots.towerMin) return [tower, true];
  const sky = dots.skyRadius * (1 - Math.min(1, tone / dots.skyShrink));
  return [sky > 0.04 ? sky : 0, false];
}

/** A custom property holding a px or rem length, in px. */
function cssLength(element: Element, property: string, fallback: number) {
  const raw = getComputedStyle(element).getPropertyValue(property).trim();
  const value = parseFloat(raw);
  if (Number.isNaN(value)) return fallback;
  if (raw.endsWith("rem")) {
    return (
      value * parseFloat(getComputedStyle(document.documentElement).fontSize)
    );
  }
  return value;
}

export function DotMatrixCanvas() {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ringRef = useRef<HTMLSpanElement>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const wrapper = wrapperRef.current;
    const canvas = canvasRef.current;
    const ring = ringRef.current;
    const context = canvas?.getContext("2d");
    if (!wrapper || !canvas || !ring || !context) return; // the poster stays

    let width = 0;
    let height = 0;
    let reach = 0; // lens radius
    // Sky dots first, then the tower: [0, skyCount) and [skyCount, count).
    let count = 0;
    let skyCount = 0;
    let homeX = new Float32Array(0);
    let homeY = new Float32Array(0);
    let radius = new Float32Array(0);
    let offsetX = new Float32Array(0);
    let offsetY = new Float32Array(0);

    const pointer = { x: 0, y: 0, active: false };
    let visible = true;
    let driftStart = -1;
    let frameId = 0;
    let ink = "";

    function readInk() {
      ink = getComputedStyle(wrapper!).color;
    }

    function layout() {
      const rect = wrapper!.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      if (!width || !height) return;

      const ratio = Math.min(devicePixelRatio, 2);
      canvas!.width = Math.round(width * ratio);
      canvas!.height = Math.round(height * ratio);
      context!.setTransform(ratio, 0, 0, ratio, 0, 0);
      reach = cssLength(wrapper!, "--cell", 75);

      // Cover: the square lattice spans the longer side, centred.
      const { columns, rows } = dots;
      const side = Math.max(width, height);
      const cell = side / columns;
      const left = (width - side) / 2;
      const top = (height - side) / 2;

      const sky: number[] = [];
      const tower: number[] = [];
      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < columns; col++) {
          const x = left + (col + 0.5 + (row % 2) * 0.5) * cell;
          const y = top + (row + 0.5) * cell;
          if (x < -cell || x > width + cell || y < -cell || y > height + cell)
            continue;
          const [r, isTower] = dotOf(tones[row * columns + col] / 255);
          if (r) (isTower ? tower : sky).push(x, y, r * cell);
        }
      }
      const all = [...sky, ...tower];
      count = all.length / 3;
      skyCount = sky.length / 3;
      homeX = new Float32Array(count);
      homeY = new Float32Array(count);
      radius = new Float32Array(count);
      offsetX = new Float32Array(count);
      offsetY = new Float32Array(count);
      for (let i = 0; i < count; i++) {
        homeX[i] = all[i * 3];
        homeY[i] = all[i * 3 + 1];
        radius[i] = all[i * 3 + 2];
      }
    }

    function draw(now: number) {
      frameId = 0;
      if (driftStart < 0) driftStart = now;
      const elapsed = now - driftStart;
      // 0 → 1 → 0 over DRIFT_MS, then still.
      const drift =
        elapsed < DRIFT_MS
          ? Math.sin((Math.PI * elapsed) / DRIFT_MS) * DRIFT_AMPLITUDE
          : 0;
      let moving = drift > 0;

      const c = context!;
      c.clearRect(0, 0, width, height);
      c.fillStyle = ink;
      const reach2 = reach * reach;

      for (let i = 0; i < count; i++) {
        if (i === 0 || i === skyCount) {
          if (i) c.fill();
          c.globalAlpha = i < skyCount ? dots.skyOpacity : 1;
          c.beginPath();
        }

        let targetX = 0;
        let targetY = 0;
        if (pointer.active) {
          const dx = homeX[i] - pointer.x;
          const dy = homeY[i] - pointer.y;
          const distance2 = dx * dx + dy * dy;
          if (distance2 < reach2) {
            const distance = Math.sqrt(distance2) || 1;
            const falloff = 1 - distance / reach;
            const push = falloff * falloff * reach * PUSH;
            targetX = (dx / distance) * push;
            targetY = (dy / distance) * push;
          }
        }
        offsetX[i] += (targetX - offsetX[i]) * EASE;
        offsetY[i] += (targetY - offsetY[i]) * EASE;
        if (
          Math.abs(targetX - offsetX[i]) > REST ||
          Math.abs(targetY - offsetY[i]) > REST
        ) {
          moving = true;
        }

        const phase = homeX[i] * 0.021 + homeY[i] * 0.013;
        const x =
          homeX[i] + offsetX[i] + Math.sin(elapsed * 0.0011 + phase) * drift;
        const y =
          homeY[i] + offsetY[i] + Math.cos(elapsed * 0.0009 + phase) * drift;
        const r = radius[i];
        c.moveTo(x + r, y);
        c.arc(x, y, r, 0, Math.PI * 2);
      }
      if (count) c.fill();
      c.globalAlpha = 1;

      if (moving) schedule();
    }

    function schedule() {
      if (!frameId && visible && count) frameId = requestAnimationFrame(draw);
    }

    function setVisible(next: boolean) {
      visible = next;
      if (visible) schedule();
      else if (frameId) {
        cancelAnimationFrame(frameId);
        frameId = 0;
      }
    }

    function onPointerMove(event: PointerEvent) {
      pointer.x = event.offsetX;
      pointer.y = event.offsetY;
      pointer.active = true;
      ring!.style.transform = `translate(${pointer.x - reach}px, ${pointer.y - reach}px)`;
      ring!.dataset.active = "";
      schedule();
    }

    function onPointerEnd() {
      pointer.active = false;
      delete ring!.dataset.active;
      schedule();
    }

    readInk();
    layout();
    // Reveal once the first frame is on the canvas.
    const firstFrame = requestAnimationFrame((now) => {
      draw(now);
      setReady(true);
    });

    const resize = new ResizeObserver(() => {
      layout();
      schedule();
    });
    resize.observe(wrapper);

    // The ink follows the theme (html[data-theme]) and forced colours.
    const onInkChange = () => {
      readInk();
      schedule();
    };
    const theme = new MutationObserver(onInkChange);
    theme.observe(document.documentElement, {
      attributeFilter: ["data-theme"],
    });
    const forcedColors = matchMedia("(forced-colors: active)");
    forcedColors.addEventListener("change", onInkChange);

    const onVisibility = (event: Event) =>
      setVisible(!(event as ContentVisibilityAutoStateChangeEvent).skipped);
    let intersection: IntersectionObserver | undefined;
    if ("contentVisibility" in document.documentElement.style) {
      wrapper.addEventListener(
        "contentvisibilityautostatechange",
        onVisibility,
      );
    } else {
      intersection = new IntersectionObserver(
        ([entry]) => setVisible(entry.isIntersecting),
        { rootMargin: "200px" },
      );
      intersection.observe(wrapper);
    }

    canvas.addEventListener("pointermove", onPointerMove);
    canvas.addEventListener("pointerdown", onPointerMove);
    canvas.addEventListener("pointerleave", onPointerEnd);
    canvas.addEventListener("pointerup", onPointerEnd);
    canvas.addEventListener("pointercancel", onPointerEnd);

    return () => {
      cancelAnimationFrame(firstFrame);
      cancelAnimationFrame(frameId);
      resize.disconnect();
      theme.disconnect();
      forcedColors.removeEventListener("change", onInkChange);
      intersection?.disconnect();
      wrapper.removeEventListener(
        "contentvisibilityautostatechange",
        onVisibility,
      );
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerdown", onPointerMove);
      canvas.removeEventListener("pointerleave", onPointerEnd);
      canvas.removeEventListener("pointerup", onPointerEnd);
      canvas.removeEventListener("pointercancel", onPointerEnd);
    };
  }, []);

  return (
    <div
      ref={wrapperRef}
      data-ready={ready || undefined}
      className="peer invisible absolute inset-0 z-10 text-ink [content-visibility:auto] data-ready:visible data-ready:motion-safe:animate-emblem-in forced-colors:text-[CanvasText]"
    >
      <canvas ref={canvasRef} aria-hidden className="size-full touch-pan-y" />
      <span
        ref={ringRef}
        aria-hidden
        className="pointer-events-none absolute top-0 left-0 size-cells-2 rounded-full border border-accent-ring opacity-0 transition-opacity duration-200 data-active:opacity-100"
      />
    </div>
  );
}
